function checkSuccess(A, buckets) {
  var wrongNodes = [], wrongBuckets = [], messages = [];
  var seen = {};
  function key(v) { return String(Math.round(v * 1000000) / 1000000); }
  A.forEach(function (v) {
    seen[key(v)] = (seen[key(v)] || 0) + 1;
    if (!(v >= 0 && v < 1)) messages.push(fmtValue(v) + ' is outside [0,1)');
  });
  var out = [], got = {};
  for (var k = 0; k < 10; k++) {
    var list = buckets[k] || [];
    for (var j = 0; j < list.length; j++) {
      var v = list[j].value;
      got[key(v)] = (got[key(v)] || 0) + 1;
      out.push(v);
      if (v >= 0 && v < 1 && Math.floor(10 * v) !== k) {
        wrongNodes.push(list[j].id); wrongBuckets.push(k);
        messages.push(fmtValue(v) + ' is in B[' + k + '] but belongs in B[' + Math.floor(10 * v) + ']');
      }
      if (j > 0 && list[j - 1].value > v) {
        wrongNodes.push(list[j - 1].id); wrongNodes.push(list[j].id); wrongBuckets.push(k);
        messages.push('B[' + k + '] is not internally sorted');
      }
    }
  }
  Object.keys(seen).forEach(function (kk) {
    if (seen[kk] !== got[kk]) messages.push('The output does not contain the same multiset of values as A');
  });
  for (var q = 1; q < out.length; q++) {
    if (out[q - 1] > out[q]) messages.push('Concatenating buckets is not globally sorted');
  }
  return {
    ok: messages.length === 0,
    message: messages.length ? messages[0] : 'Correct: each value is in bucket floor(10x), each list is sorted, and bucket concatenation is globally sorted.',
    wrongNodes: Array.from(new Set(wrongNodes)),
    wrongBuckets: Array.from(new Set(wrongBuckets))
  };
}

function runBucketSortCode() {
  stopPlay();
  showingGuide = false;
  var A;
  try {
    A = parseInputValues();
  } catch (e) {
    var st = buildFinalState([]);
    frames = [{ kind: 'error', state: st, indices: {}, message: 'Input error: ' + e.message }];
    frameIndex = 0;
    drawFigure(frames[0]);
    updatePlaybackUi();
    setStatus('error', '#b00000');
    return;
  }

  document.getElementById('bucketSortCodeRun').disabled = true;
  setStatus('running', '#a05a00');
  frames = [];
  frameIndex = -1;
  updatePlaybackUi();

  var workerScript = `
    onmessage = function(e) {
      var A = e.data.A.slice();
      var code = e.data.code;
      var buckets = Array.from({length:10}, function(){ return null; });
      var nodes = {};
      var nextId = 1, frames = [], opCount = 0;
      var FRAME_CAP = 3000, OP_CAP = 10000;
      function copyState() {
        var bs = [];
        for (var k=0;k<10;k++) {
          var arr = [], id = buckets[k], guard = 0;
          while (id !== null && guard++ < 1000) {
            arr.push({ id:id, value:nodes[id].value });
            id = nodes[id].next;
          }
          bs[k] = arr;
        }
        return { A:A.slice(), buckets:bs };
      }
      function rec(kind, indices, message) {
        opCount++;
        if (opCount > OP_CAP) throw new Error('Operation cap reached; possible infinite loop.');
        if (frames.length >= FRAME_CAP) throw new Error('Frame cap reached; trace is too long.');
        frames.push({ kind:kind, state:copyState(), indices:indices || {}, message:message || kind });
      }
      function validBucket(k) {
        if (!(k >= 0 && k < 10) || Math.floor(k) !== k) throw new Error('Bucket index ' + k + ' is outside 0..9.');
      }
      function handle(id) { return id === null ? null : Object.freeze({ __nodeId:id }); }
      function getId(node) {
        if (node === null) return null;
        if (!node || !nodes[node.__nodeId]) throw new Error('Invalid node handle.');
        return node.__nodeId;
      }
      function len(_) { rec('len', {}, 'len(A) → ' + A.length); return A.length; }
      function readA(i) {
        if (i < 0 || i >= A.length || Math.floor(i) !== i) throw new Error('readA index ' + i + ' is out of range.');
        rec('readA', {a:i}, 'readA(' + i + ') → ' + A[i]);
        return A[i];
      }
      function head(k) {
        validBucket(k);
        rec('head', {bucket:k}, 'head(' + k + ') selects interval [' + (k/10) + ', ' + ((k+1)/10) + ')');
        return handle(buckets[k]);
      }
      function next(node) {
        var id = getId(node), n = nodes[id].next;
        rec('next', {nodes:[id]}, 'next(' + nodes[id].value + ') → ' + (n === null ? 'null' : nodes[n].value));
        return handle(n);
      }
      function lessValue(node, x) {
        var id = getId(node), ans = nodes[id].value < x;
        rec('lessValue', {nodes:[id]}, 'compare ' + nodes[id].value + ' < ' + x + ' → ' + ans);
        return ans;
      }
      function insertAfter(k, prevNode, x) {
        validBucket(k);
        var prev = getId(prevNode);
        var id = 'n' + (nextId++);
        nodes[id] = { value:x, next:null };
        if (prev === null) {
          nodes[id].next = buckets[k];
          buckets[k] = id;
        } else {
          var scan = buckets[k], ok = false;
          while (scan !== null) { if (scan === prev) { ok = true; break; } scan = nodes[scan].next; }
          if (!ok) throw new Error('prevNode is not in bucket ' + k + '.');
          nodes[id].next = nodes[prev].next;
          nodes[prev].next = id;
        }
        rec('insertAfter', {bucket:k, newNode:id, nodes: prev ? [prev] : []}, 'insert ' + x + (prev ? ' after ' + nodes[prev].value : ' at the head') + ' of B[' + k + ']');
        return handle(id);
      }
      function note(message) {
        rec('note', {}, String(message));
      }
      try {
        var factory = new Function('A','len','readA','head','next','lessValue','insertAfter','note', code + '\\n; return (typeof bucketSort === "function") ? bucketSort : null;');
        var entry = factory(Object.freeze({length:A.length}), len, readA, head, next, lessValue, insertAfter, note);
        if (typeof entry !== 'function') throw new Error('Missing entry point: define function bucketSort(A).');
        entry(Object.freeze({length:A.length}));
        postMessage({ ok:true, frames:frames, finalState:copyState() });
      } catch (err) {
        frames.push({ kind:'error', state:copyState(), indices:{}, message:'Error: ' + (err && err.message ? err.message : err) });
        postMessage({ ok:false, frames:frames, finalState:copyState(), error:String(err && err.message ? err.message : err) });
      }
    };
  `;
  var blob = new Blob([workerScript], { type: 'application/javascript' });
  var url = URL.createObjectURL(blob);
  activeWorker = new Worker(url);
  var done = false;
  var timeout = setTimeout(function () {
    if (done) return;
    done = true;
    activeWorker.terminate();
    URL.revokeObjectURL(url);
    document.getElementById('bucketSortCodeRun').disabled = false;
    var st = buildFinalState([]);
    frames = [{ kind: 'error', state: st, indices: {}, message: 'Error: timed out; possible infinite loop.' }];
    frameIndex = 0;
    drawFigure(frames[0]);
    updatePlaybackUi();
    setStatus('error', '#b00000');
  }, 1800);

  activeWorker.onmessage = function (ev) {
    if (done) return;
    done = true;
    clearTimeout(timeout);
    activeWorker.terminate();
    URL.revokeObjectURL(url);
    document.getElementById('bucketSortCodeRun').disabled = false;
    var data = ev.data;
    frames = data.frames || [];
    if (data.finalState) {
      var result = checkSuccess(A, data.finalState.buckets);
      frames.push({
        kind: result.ok ? 'complete' : 'error',
        state: data.finalState,
        indices: { wrongNodes: result.wrongNodes, wrongBuckets: result.wrongBuckets },
        message: result.message
      });
      setStatus(result.ok ? 'correct' : 'wrong answer', result.ok ? '#16833a' : '#b00000');
    } else {
      setStatus('error', '#b00000');
    }
    frameIndex = 0;
    drawFigure(frames[0] || staticDefaultFrame);
    updatePlaybackUi();
  };
}

